#!/usr/bin/env node
// Generates the API reference of the bundled core and std (src/content/docs/std/api/)
// from `emela doc --std --format md`.
//
// The pages are generated; do not edit them by hand. Rerun this script whenever the
// emela the docs follow is bumped (and commit the result):
//
//   EMELA=/path/to/emela node scripts/gen-std-api.mjs
//
// EMELA defaults to the `emela` on PATH. The script deletes src/content/docs/std/api/,
// runs `emela doc` into a temporary directory and writes one page per module:
//
// - `Std.Http.Request.md` becomes `std-http-request.md` (URL /std/api/std-http-request/).
// - The `# Module` heading becomes the frontmatter title (Starlight renders it as the h1).
// - The headings `## Types` and `## Values` become `## 型` and `## 値`.
// - Links between the generated files (`[List](List.md)`) point to the page URLs.
// - The code blocks stay plain ```emela, which scripts/check-examples.mjs does not check:
//   signatures are not programs.

import { execFileSync } from 'node:child_process';
import { mkdtempSync, mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

const EMELA = process.env.EMELA ?? 'emela';
const ROOT = new URL('..', import.meta.url).pathname;
const OUT = join(ROOT, 'src/content/docs/std/api');

const version = execFileSync(EMELA, ['--version'], { encoding: 'utf-8' }).trim().replace(/^emela\s+/, '').replace(/\+.*$/, '');
const work = mkdtempSync(join(tmpdir(), 'emela-doc-'));
execFileSync(EMELA, ['doc', '--std', '--format', 'md', '--out-dir', join(work, 'doc')], {
  cwd: work,
  stdio: ['ignore', 'ignore', 'inherit'],
});
const src = join(work, 'doc');

const slug = (module) => module.toLowerCase().replaceAll('.', '-');
const url = (module) => `/std/api/${slug(module)}/`;
const fixLinks = (text) => text.replace(/\]\(([A-Za-z0-9.]+)\.md\)/g, (_, m) => `](${url(m)})`);
// The section headings `emela doc` writes, in the language of the site.
const localize = (text) => text.replace(/^## Types$/gm, '## 型').replace(/^## Values$/gm, '## 値');
const yaml = (s) => JSON.stringify(s);

// Order in the sidebar: the list page, Prelude, the core modules, then Std.*.
const order = (module) => (module === 'Prelude' ? 1 : module.startsWith('Std.') ? 3 : 2);

rmSync(OUT, { recursive: true, force: true });
mkdirSync(OUT, { recursive: true });

const modules = readdirSync(src)
  .filter((f) => f.endsWith('.md') && f !== 'index.md')
  .map((f) => f.slice(0, -3))
  .sort();

for (const module of modules) {
  const text = readFileSync(join(src, `${module}.md`), 'utf-8');
  const body = text.replace(/^# .*\n+/, '');
  const kind = module.startsWith('Std.') ? 'std' : 'core';
  const front = [
    '---',
    `title: ${yaml(module)}`,
    `description: ${yaml(`${kind} のモジュール ${module} の型と関数（emela doc から生成）`)}`,
    'sidebar:',
    `  order: ${order(module)}`,
    'editUrl: false',
    '---',
    '',
    `<!-- Generated by scripts/gen-std-api.mjs from \`emela doc --std\` (${version}). Do not edit. -->`,
    '',
    '',
  ].join('\n');
  writeFileSync(join(OUT, `${slug(module)}.md`), front + localize(fixLinks(body)).trimEnd() + '\n');
}

const list = (ms) => ms.map((m) => `- [${m}](${url(m)})`).join('\n');
const core = modules.filter((m) => !m.startsWith('Std.'));
const std = modules.filter((m) => m.startsWith('Std.'));
writeFileSync(
  join(OUT, 'index.md'),
  `---
title: API リファレンス
description: core と std の全モジュールの型と関数。emela doc --std から生成
sidebar:
  label: モジュールの一覧
  order: 0
editUrl: false
---

<!-- Generated by scripts/gen-std-api.mjs from \`emela doc --std\` (${version}). Do not edit. -->

同梱の core と std の、公開されている型と関数の一覧です。emela ${version} の \`emela doc --std\` が、ソースのドキュメントコメント（英語）から作ったものです。使い方の説明は [標準ライブラリの構成](/std/overview/) から各ページにあります。

手元の emela で同じものを見るには \`emela doc --std\` を実行し、\`target/emela/doc/\` を開きます。

## core

import なしで使えます。Prelude の名前は修飾なしで、ほかは \`List.map\` のようにモジュール名で修飾して呼びます。

${list(core)}

## std

\`import Std.Console.{Console}\` のように import して使います。

${list(std)}
`,
);

rmSync(work, { recursive: true, force: true });
console.log(`wrote ${modules.length + 1} pages to ${OUT} (emela ${version})`);
